342	    /**
343	     * Builds the owner's customer code as {@code '<REGION>-<HASH8>'}, where {@code REGION} is the
344	     * region derived from the owner's postcode (falling back to its city, else {@code 'UNKNOWN'}) via
345	     * {@link OwnerMapper#toRegion}, and {@code HASH8} is the first 8 upper-case hex characters of the
346	     * SHA-256 digest of {@code normalizedTelephone + lastName} (e.g. {@code NSW-1A2B3C4D}).
347	     *
348	     * <p>When the computed code collides with an existing owner's {@code customerCode}, it is
349	     * de-duplicated by appending {@code '-<n>'} with the smallest {@code n} of 2 or more that makes it
350	     * unique (e.g. {@code NSW-1A2B3C4D-2}); the de-duplicated code is returned. Absent a collision the
351	     * base region-and-hash code is returned unchanged.
352	     *
353	     * @param owner the owner being created, with its region-determining postcode and city populated
354	     * @param normalizedTelephone the owner's normalized (E.164) telephone, hashed with the last name
355	     * @return the (de-duplicated) region-and-hash customer code for the owner being created
356	     */
357	    private String buildCustomerCode(Owner owner, String normalizedTelephone) {
358	        String region = ownerMapper.toRegion(owner);
359	        String hash8 = sha256Hex8(normalizedTelephone + owner.getLastName());
360	        String baseCode = region + "-" + hash8;
361	        Set<String> existingCodes = this.clinicService.findAllOwners().stream()
362	            .map(Owner::getCustomerCode)
363	            .filter(java.util.Objects::nonNull)
364	            .collect(java.util.stream.Collectors.toSet());
365	        if (!existingCodes.contains(baseCode)) {
366	            return baseCode;
367	        }
368	        int n = 2;
369	        while (existingCodes.contains(baseCode + "-" + n)) {
370	            n++;
371	        }
372	        return baseCode + "-" + n;
373	    }
374	
375	    /**
376	     * Returns the first 8 upper-case hex characters of the SHA-256 digest of {@code value}'s UTF-8
377	     * bytes. Deterministic, so the same input always yields the same 8-character hash.
378	     */
379	    private static String sha256Hex8(String value) {
380	        try {
381	            byte[] digest = MessageDigest.getInstance("SHA-256")
382	                .digest(value.getBytes(StandardCharsets.UTF_8));
383	            StringBuilder sb = new StringBuilder();
384	            for (byte b : digest) {
385	                sb.append(String.format("%02X", b));
386	            }
387	            return sb.substring(0, 8);
388	        }
389	        catch (NoSuchAlgorithmException e) {
390	            throw new IllegalStateException("SHA-256 not available", e);
391	        }
392	    }
