483	     * Validates and normalizes an owner's email address. A syntactically valid address is required;
484	     * the value is returned lower-cased so it is stored and echoed back in canonical form.
485	     *
486	     * @param email the raw email value from the request (already known to be non-null)
487	     * @return the lower-cased email to be stored and returned
488	     * @throws InvalidFieldValueException if the value is not a syntactically valid email address
489	     */
490	    private static String normalizeEmail(String email) {
491	        String trimmed = email.trim();
492	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
493	            throw new InvalidFieldValueException("email", "Email must be a syntactically valid address");
494	        }
495	        String canonical = trimmed.toLowerCase(Locale.ROOT);
496	        String domain = canonical.substring(canonical.indexOf('@') + 1);
