512	     * @throws CityAtCapacityException if the city is already at or above its owner capacity
513	     */
514	    /** The maximum number of owners that may be registered in a single day; the {@code (100 + 1)}th is rejected. */
515	    private static final int MAX_OWNERS_PER_DAY = 100;
