517	    /**
518	     * Rejects the request when {@link #MAX_OWNERS_PER_DAY} or more owners have already been registered
519	     * on {@code businessDay}, counting existing owners whose {@code registrationDate} equals that date.
520	     * New owners take {@code businessDay} as their {@code registrationDate} (the supplied or defaulted
521	     * date rolled forward to a business day), so this caps the number that may be created per day.
522	     *
523	     * @param businessDay the adjusted business-day registration date of the owner being created
524	     * @throws DailyOwnerLimitException if the daily owner-creation limit has already been reached
525	     */
526	    /**
527	     * The number of owners for a single day beyond which the {@code bulkSignupWarning} flag is
528	     * raised; the warning is true once <em>more than</em> this many owners share a registration date.
529	     */
530	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
531	
532	    /**
533	     * Maps {@code owner} to its DTO and sets the {@code bulkSignupWarning} flag: {@code true} when
534	     * more than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners have already been created for this
535	     * owner's registration date, otherwise {@code false}.
536	     *
537	     * @param owner the owner to map
538	     * @return the owner DTO with its bulk-signup warning flag populated
539	     */
540	    private OwnerDto toOwnerDtoWithBulkWarning(Owner owner) {
541	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
542	        ownerDto.setBulkSignupWarning(exceedsBulkSignupThreshold(owner.getRegistrationDate()));
543	        int points = OwnerMapper.membershipPointsFor(owner, householdSize(owner.getHouseholdId()));
544	        ownerDto.setMembershipPoints(points);
545	        ownerDto.setMembershipLevel(capMembershipLevel(owner, OwnerMapper.membershipLevelFor(points)));
546	        return ownerDto;
547	    }
548	
549	    /**
550	     * Caps the owner's {@code membershipLevel} so it cannot exceed one above the current maximum
551	     * membership level among the other members of its household (existing owners carrying the same
552	     * {@code householdId}, excluding the owner itself and any soft-deleted owner). When the household
553	     * has no other member — including when the owner has no {@code householdId} — no cap applies and
554	     * {@code level} is returned unchanged. Each household member's level is its own base level (points
555	     * mapped to a level for its real household size), so the cap does not depend on other capped
556	     * values.
557	     *
558	     * @param owner the owner whose membership level is being computed
559	     * @param level the owner's uncapped membership level derived from its membership points
560	     * @return the membership level capped at {@code maxHouseholdMemberLevel + 1}, or {@code level}
561	     *         when the owner has no other household member
562	     */
563	    private int capMembershipLevel(Owner owner, int level) {
564	        String householdId = owner.getHouseholdId();
565	        if (householdId == null) {
566	            return level;
567	        }
568	        Integer maxMemberLevel = this.clinicService.findAllOwners().stream()
569	            .filter(existing -> !isDeleted(existing))
570	            .filter(existing -> !java.util.Objects.equals(existing.getId(), owner.getId()))
571	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
572	            .map(this::membershipLevelForOwner)
573	            .max(Integer::compareTo)
574	            .orElse(null);
575	        if (maxMemberLevel == null) {
576	            return level;
577	        }
578	        return Math.min(level, maxMemberLevel + 1);
579	    }
580	
581	    /**
582	     * Computes an existing household member's membership level: its membership points for its real
583	     * household size mapped to the numeric level. Used to establish the household's current maximum
584	     * level when capping a new owner's level.
585	     */
586	    private int membershipLevelForOwner(Owner owner) {
587	        int points = OwnerMapper.membershipPointsFor(owner, householdSize(owner.getHouseholdId()));
588	        return OwnerMapper.membershipLevelFor(points);
589	    }
