633	    /**
634	     * Fixed list of public holidays. A registration date landing on one of these dates is rolled
635	     * forward, just like a weekend, until it reaches a non-holiday business day.
636	     */
637	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
638	        LocalDate.of(2026, 1, 1),
639	        LocalDate.of(2026, 1, 26),
640	        LocalDate.of(2026, 4, 25),
641	        LocalDate.of(2026, 12, 25),
642	        LocalDate.of(2026, 12, 28));
643	
644	    /**
645	     * Rolls {@code date} forward to a business day: while it falls on a Saturday, Sunday, or a listed
646	     * public holiday it advances one day at a time until it reaches a non-holiday weekday. Applied to
647	     * the effective registration date (whether supplied in the request or defaulted to the server date)
648	     * so a weekend or holiday registration is recorded on the next business day, and every value derived
649	     * from the registration date uses the adjusted date.
650	     *
651	     * @param date the effective registration date (supplied or defaulted), never {@code null}
652	     * @return the same date, or the next non-holiday business day when {@code date} is a weekend or holiday
653	     */
654	    private static LocalDate toBusinessDay(LocalDate date) {
655	        LocalDate adjusted = date;
656	        while (isWeekend(adjusted) || PUBLIC_HOLIDAYS.contains(adjusted)) {
657	            adjusted = adjusted.plusDays(1);
658	        }
659	        return adjusted;
660	    }
