662	    /** Whether {@code date} falls on a Saturday or Sunday. */
663	    private static boolean isWeekend(LocalDate date) {
664	        DayOfWeek day = date.getDayOfWeek();
665	        return day == DayOfWeek.SATURDAY || day == DayOfWeek.SUNDAY;
666	    }
