668	    /** Matches a well-formed postcode: exactly four decimal digits. */
669	    private static final Pattern POSTCODE_PATTERN = Pattern.compile("^[0-9]{4}$");
670	
671	    /**
672	     * Fixed region-to-postcode range table: each region admits an inclusive 4-digit range
673	     * ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}). Regions are derived
674	     * from the owner's city via {@link OwnerMapper#CITY_REGION}; a city with no known region is not
675	     * present here and accepts any well-formed postcode.
676	     */
677	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
678	        "NSW", new int[] {2000, 2099},
679	        "VIC", new int[] {3000, 3099},
680	        "QLD", new int[] {4000, 4099});
681	
682	    /**
683	     * Validates an owner's optional {@code postcode}. When absent nothing is checked (postcode is
684	     * optional, so the request contract stays backward-compatible). When present it must be exactly
685	     * four digits and, for a city whose region is known, fall within that region's inclusive range
686	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099); a city with no known region accepts any 4-digit
687	     * postcode. A malformed or out-of-range value is rejected with a 400.
688	     *
689	     * @param postcode the raw postcode from the request (may be {@code null} when not supplied)
690	     * @param city the owner's city, used to look up the region whose range constrains the postcode
691	     * @throws InvalidFieldValueException if the postcode is present but malformed or out of range
692	     */
693	    private void validatePostcode(String postcode, String city) {
694	        if (postcode == null) {
695	            return;
696	        }
697	        if (!POSTCODE_PATTERN.matcher(postcode).matches()) {
698	            throw new InvalidFieldValueException("postcode", "Postcode must be exactly four digits");
699	        }
700	        String region = OwnerMapper.CITY_REGION.getOrDefault(city, "UNKNOWN");
701	        int[] range = REGION_POSTCODES.get(region);
702	        if (range == null) {
703	            return;
704	        }
705	        int value = Integer.parseInt(postcode);
706	        if (value < range[0] || value > range[1]) {
707	            throw new InvalidFieldValueException("postcode",
708	                "Postcode must be valid for the city's region " + region);
709	        }
710	    }
