746	     *
747	     * @param owner the incoming owner, with its normalized telephone, email and last name
748	     *              already populated
749	     * @throws DuplicateIdentityException if another owner already has this exact identity key
750	     */
751	    private void requireUniqueIdentity(Owner owner) {
752	        String identityKey = ownerMapper.toIdentityKey(owner);
753	        boolean taken = this.clinicService.findAllOwners().stream()
754	            .filter(existing -> !isDeleted(existing))
755	            .map(ownerMapper::toIdentityKey)
756	            .anyMatch(identityKey::equals);
757	        if (taken) {
758	            throw new DuplicateIdentityException(identityKey);
759	        }
760	    }
761	
762	    /**
763	     * Returns whether an existing owner has been soft-deleted. A soft-deleted owner retains its row
764	     * but is ignored by the create endpoint's duplicate and identity checks, so a normally-blocking
765	     * duplicate is allowed when the only matching owner has been deleted.
766	     */
767	    private static boolean isDeleted(Owner owner) {
768	        return Boolean.TRUE.equals(owner.getDeleted());
769	    }
770	
771	    /**
772	     * Flags the incoming owner as a possible (soft) duplicate. Called after the hard-duplicate identity
773	     * check has passed, so the owner is known not to be a rejected duplicate. When an existing owner
774	     * has the same {@code soundex(lastName)} and the same {@code postcode} as this owner but a
775	     * <em>different</em> {@code identityKey}, the owner is a possible duplicate: {@code possibleDuplicate}
776	     * is set {@code true} and {@code possibleDuplicateOf} to that existing owner's id (the earliest such
777	     * owner by id when more than one matches). Otherwise both are cleared. A declared household member
778	     * ({@code sharesHousehold} true) is never flagged: it is a deliberate member, not a suspected
779	     * duplicate. An owner with no {@code postcode} never matches, since the soft match is keyed on it.
780	     *
781	     * @param owner the incoming owner, with its telephone, email and postcode populated
782	     * @param sharesHousehold whether the request opted in as a declared household member
783	     */
784	    private void markPossibleDuplicate(Owner owner, boolean sharesHousehold) {
785	        owner.setPossibleDuplicate(false);
786	        owner.setPossibleDuplicateOf(null);
787	        if (sharesHousehold) {
788	            return;
789	        }
790	        String postcode = owner.getPostcode();
791	        if (postcode == null || postcode.isBlank()) {
792	            return;
793	        }
794	        String soundex = OwnerIdentity.soundex(owner.getLastName());
795	        String identityKey = ownerMapper.toIdentityKey(owner);
796	        this.clinicService.findAllOwners().stream()
797	            .filter(existing -> !isDeleted(existing))
798	            .filter(existing -> postcode.equals(existing.getPostcode()))
799	            .filter(existing -> soundex.equals(OwnerIdentity.soundex(existing.getLastName())))
800	            .filter(existing -> !identityKey.equals(ownerMapper.toIdentityKey(existing)))
801	            .min(java.util.Comparator.comparing(Owner::getId))
802	            .ifPresent(match -> {
803	                owner.setPossibleDuplicate(true);
804	                owner.setPossibleDuplicateOf(match.getId());
805	            });
806	    }
807	
808	    /**
809	     * Normalizes a value for household-duplicate comparison: trims leading and trailing whitespace,
810	     * collapses every internal run of whitespace to a single space, and lower-cases the result so
811	     * comparisons are case-insensitive.
812	     */
813	    private static String normalizeForHousehold(String value) {
814	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
815	    }
816	
817	    /**
818	     * Normalizes an owner's address to its canonical stored form: leading and trailing whitespace is
819	     * trimmed, every internal run of whitespace is collapsed to a single space, the value is
820	     * upper-cased, and common street-type abbreviations are expanded on a whole-word basis
821	     * ({@code ST->STREET}, {@code RD->ROAD}, {@code AVE->AVENUE}). A {@code null} or whitespace-only
822	     * value normalizes to the empty string, so the required-field check rejects an address that is
823	     * blank once normalized. For example {@code "  12  main  st "} becomes {@code "12 MAIN STREET"}.
824	     *
825	     * @param address the raw address value from the request (may be {@code null})
826	     * @return the normalized address, or the empty string when blank after normalization
827	     */
828	    private static String normalizeAddress(String address) {
829	        if (address == null) {
830	            return "";
831	        }
832	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
833	        if (collapsed.isEmpty()) {
834	            return "";
835	        }
836	        String[] tokens = collapsed.split(" ");
837	        StringBuilder sb = new StringBuilder();
838	        for (String token : tokens) {
839	            String expanded = switch (token) {
840	                case "ST" -> "STREET";
841	                case "RD" -> "ROAD";
842	                case "AVE" -> "AVENUE";
843	                default -> token;
844	            };
845	            if (sb.length() > 0) {
846	                sb.append(' ');
847	            }
848	            sb.append(expanded);
849	        }
850	        return sb.toString();
851	    }
852	
853	    /**
854	     * Composes the stored/returned {@code address} from the normalized structured lines: the
855	     * normalized {@code addressLine1}, with a single space and the normalized {@code addressLine2}
856	     * appended when {@code addressLine2} is present (non-empty). Both arguments are already
857	     * normalized via {@link #normalizeAddress(String)}.
858	     *
859	     * @param normalizedAddressLine1 the normalized first address line (non-empty)
860	     * @param normalizedAddressLine2 the normalized second address line, or the empty string when absent
861	     * @return the composed address string
862	     */
863	    private static String composeAddress(String normalizedAddressLine1, String normalizedAddressLine2) {
864	        if (normalizedAddressLine2.isEmpty()) {
865	            return normalizedAddressLine1;
866	        }
867	        return normalizedAddressLine1 + " " + normalizedAddressLine2;
868	    }
869	
870	    /**
871	     * Derives the stable household identifier for an owner from its last name and postcode as the
872	     * upper-cased first 12 hex characters of the SHA-256 digest of
873	     * {@code normalizedLastName + '|' + postcode}, where the last name is normalized (trimmed,
874	     * internal whitespace collapsed, lower-cased) so casing and spacing do not affect it. Because the
875	     * identifier is a deterministic function of the normalized last name and postcode, owners that
876	     * share a last name and postcode share the identifier automatically — no back-fill or opt-in is
877	     * required. Returns {@code null} when no postcode is present, since the household is keyed on the
878	     * postcode and there is then nothing to key on.
879	     *
880	     * @param lastName the owner's last name (already validated non-blank)
881	     * @param postcode the owner's postcode (a validated 4-digit value, or {@code null} when absent)
882	     * @return the 12-hex-character household identifier, or {@code null} when no postcode is present
883	     */
884	    private static String householdIdFor(String lastName, String postcode) {
885	        if (postcode == null || postcode.isBlank()) {
886	            return null;
887	        }
888	        String normalizedLastName = normalizeForHousehold(lastName);
889	        try {
890	            byte[] digest = MessageDigest.getInstance("SHA-256")
891	                .digest((normalizedLastName + "|" + postcode).getBytes(StandardCharsets.UTF_8));
892	            StringBuilder sb = new StringBuilder();
893	            for (byte b : digest) {
894	                sb.append(String.format("%02X", b));
895	            }
896	            return sb.substring(0, 12);
897	        }
898	        catch (NoSuchAlgorithmException e) {
899	            throw new IllegalStateException("SHA-256 not available", e);
900	        }
901	    }
902	}
